const escape=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));

export function accountConfirmation(email,{pending=false}={}) {
  return `<section class="pull-welcome"><img src="favicon.svg" width="52" height="52" alt="Pull GTM"><p class="eyebrow">${pending?'ONE LAST STEP':'YOU’RE IN'}</p><h3>${pending?'Check your inbox.':'Welcome to Pull.'}</h3><p>${pending?'Open the confirmation email sent to':'Signed in as'} <strong>${escape(email)}</strong>.</p><p class="small-print">${pending?'Confirm your email, then return here to sign in. Check spam if it hasn’t arrived.':'Your workspace, your audience, your next opportunity.'}</p><button class="button primary" data-action="${pending?'welcome-signin':'welcome-continue'}">${pending?'Back to sign in':'Continue to my workspace'}</button></section>`;
}

export function onboardingChoices() {
  return `<p>What would you like Pull to help with? You can change this later.</p><div class="pull-goal-grid"><button class="pull-goal" data-action="onboard-professional"><span class="eyebrow">PROFESSIONAL GTM</span><h3>Build your next connection.</h3><p>Find clients, private businesses, decision makers, and career opportunities.</p><span>Set up professional workspace →</span></button><button class="pull-goal" data-action="onboard-commerce"><span class="eyebrow">COMMERCE GTM</span><h3>Find your next customer.</h3><p>Define your buyers, location, products, and the channels where you sell.</p><span>Set up commerce workspace →</span></button></div>`;
}

export function onboardingForm(state,mode) {
  const commerce=mode==='commerce';
  return `<form id="onboarding-form"><input type="hidden" name="mode" value="${commerce?'commerce':'professional'}"><p class="small-print">${commerce?'Tell Pull what you sell and who you hope to reach.':'Give Pull a brief so suggestions fit your work.'} These details guide research; they do not prove buying intent.</p><div class="field"><label for="onboard-name">${commerce?'Shop or business name':'Your name or workspace'}</label><input id="onboard-name" name="identity" maxlength="100" required value="${escape(state.identity==='Pull GTM'?'':state.identity)}" autocomplete="organization"></div>${commerce?'':`<div class="field"><label for="onboard-purpose">My main goal</label><select id="onboard-purpose" name="persona"><option value="business">Find clients and grow my business</option><option value="career" ${state.persona==='career'?'selected':''}>Find private-sector career opportunities</option></select></div>`}<div class="field"><label for="onboard-offer">${commerce?'What do you sell?':'What do you offer, or want to do?'}</label><textarea id="onboard-offer" name="offer" maxlength="1000" required placeholder="${commerce?'Fresh produce for local shops and households':'Brand design for growing private businesses'}">${escape(state.offer)}</textarea></div><div class="field"><label for="onboard-audience">${commerce?'Who would you like to sell to?':'Who would you like to reach?'}</label><input id="onboard-audience" name="roles" maxlength="300" value="${escape(state.rules.roles)}" placeholder="${commerce?'Shop owners, restaurant buyers':'Founders, marketing directors, hiring managers'}"></div><div class="field-pair"><div class="field"><label for="onboard-industry">Industry</label><input id="onboard-industry" name="industries" maxlength="300" value="${escape(state.rules.industries)}" placeholder="Optional"></div><div class="field"><label for="onboard-location">Country or region</label><input id="onboard-location" name="countries" maxlength="300" value="${escape(state.rules.countries)}" placeholder="Worldwide"></div></div><p class="form-error" role="alert" id="onboard-error"></p><div class="form-actions"><button type="button" class="button secondary" data-action="onboard-start">Back</button><button type="submit" class="button primary">Create my workspace</button></div><p class="small-print">Your existing prospects and drafts are kept. Creating your workspace saves this brief privately to your account.</p></form>`;
}

export function applyOnboarding(state,values) {
  if(!['professional','commerce'].includes(values.mode))throw new Error('Choose a workspace type.');
  const text=(key,max)=>{const value=String(values[key]||'').trim();if(value.length>max)throw new Error('Please shorten your '+key+'.');return value;};
  const identity=text('identity',100),offer=text('offer',1000);
  if(!identity||!offer)throw new Error('Add your workspace name and a short description.');
  const persona=values.mode==='commerce'?'trade':values.persona==='career'?'career':'business';
  return {...state,identity,offer,persona,context:persona==='career'?'personal':state.context,setup:true,rules:{...state.rules,roles:text('roles',300),industries:text('industries',300),countries:text('countries',300)}};
}
